<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../api/client';const items=ref<any[]>([]),roles=ref<any[]>([]),show=ref(false),form=ref({username:'',password:'',display_name:'',email:'',role_ids:[] as string[]});async function load(){const[u,r]=await Promise.all([api.get('/users',{params:{page:1,page_size:100}}),api.get('/roles')]);items.value=u.data.items||[];roles.value=r.data.items||[]}async function create(){await api.post('/users',form.value);show.value=false;await load()}async function status(x:any){await api.patch(`/users/${x.ID}/status`,{status:x.Status==='active'?'disabled':'active'});await load()}async function reset(id:string){const value=prompt('请输入新密码');if(value)await api.post(`/users/${id}/reset-password`,{new_password:value})}async function assign(x:any){const selected=prompt('请输入角色 ID，多个用逗号分隔',(x.Roles||[]).map((r:any)=>r.ID).join(','));if(selected!==null){await api.put(`/users/${x.ID}/roles`,{role_ids:selected.split(',').map(v=>v.trim()).filter(Boolean)});await load()}}onMounted(load)</script>
<template><div class="page"><div class="page-title"><div><h1>用户管理</h1><p>创建账号、启停用户、重置密码并分配业务角色</p></div><button class="primary-button" @click="show=true">＋ 新增用户</button></div><section class="card"><table class="data-table"><thead><tr><th>用户</th><th>邮箱</th><th>角色</th><th>状态</th><th>最近登录</th><th>操作</th></tr></thead><tbody><tr v-for="x in items" :key="x.ID"><td><strong>{{x.DisplayName||x.Username}}</strong><div>{{x.Username}}</div></td><td>{{x.Email||'-'}}</td><td>{{(x.Roles||[]).map((r:any)=>r.Name).join('、')||'未授权'}}</td><td>{{x.Status}}</td><td>{{x.LastLoginAt||'-'}}</td><td><div class="action-group"><button class="secondary-button" @click="assign(x)">分配角色</button><button class="secondary-button" @click="reset(x.ID)">重置密码</button><button class="primary-button" @click="status(x)">{{x.Status==='active'?'停用':'启用'}}</button></div></td></tr></tbody></table></section><div v-if="show" class="modal-mask" @click.self="show=false"><div class="modal"><div class="modal-header"><h3>新增用户</h3><button class="close-button" @click="show=false">×</button></div><div class="modal-body"><div class="form-grid"><label><span>用户名</span><input v-model="form.username"></label><label><span>显示名称</span><input v-model="form.display_name"></label><label><span>邮箱</span><input v-model="form.email"></label><label><span>初始密码</span><input v-model="form.password" type="password"></label><label class="full"><span>角色</span><select v-model="form.role_ids" multiple><option v-for="r in roles" :key="r.ID" :value="r.ID">{{r.Name}} · {{r.Description}}</option></select></label></div></div><div class="modal-footer"><button class="secondary-button" @click="show=false">取消</button><button class="primary-button" @click="create">创建</button></div></div></div></div></template>
